<article class="news-card"><?php $bild=ma_content_image(null,'large'); ?><a class="news-card__image<?php echo $bild['is_fallback']?' news-card__image--symbol':''; ?>" href="<?php the_permalink(); ?>"><img src="<?php echo esc_url($bild['url']); ?>" alt="<?php echo esc_attr($bild['alt']); ?>" loading="lazy" decoding="async"><span class="image-credit"><?php echo esc_html(ma_image_caption($bild)); ?></span></a><div><div class="eyebrow"><?php echo ma_theme_location_label(); ?> · <?php $c=get_the_category(); echo esc_html($c[0]->name??'Aktuell'); ?></div><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><?php if(has_excerpt()): ?><p><?php echo esc_html(get_the_excerpt()); ?></p><?php endif; ?><div class="meta-line"><span><?php echo esc_html(get_the_date('d.m.Y · H:i')); ?> Uhr</span><a href="<?php the_permalink(); ?>#comments"><?php echo (int)get_comments_number(); ?> Kommentare</a></div><a class="read-more" href="<?php the_permalink(); ?>">Mehr lesen</a></div></article>
